{
  "userQuery": "电量掉得太快了，帮我做个卡片显示一下当前电量，电量低提示我开启省电模式，卡片要有快速进入省电模式的功能。",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "SetSettingSwitch",
        "params": {
          "appBundleName": "com.huawei.hmos.settings",
          "itemName": "battery_saving_mode",
          "switchFlag": 0
        }
      }
    }
  ],
  "dataModel": {
    "value": {
      "battery": {
        "level": 18,
        "levelText": "18%",
        "statusText": "电量偏低",
        "hintText": "建议开启省电模式",
        "modeText": "省电模式未开启"
      }
    }
  },
  "assetCandidates": []
}

